def solve(a: str, b: str) -> int:
    m, n = len(a), len(b)
    # dp[i][j] distance for a[:i] and b[:j]
    # Use two rows to save memory
    prev = list(range(n + 1))
    for i in range(1, m + 1):
        cur = [i] + [0] * n
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j],      # deletion
                                   cur[j - 1],  # insertion
                                   prev[j - 1]) # substitution
        prev = cur
    return prev[n]

