    The function is tolerant of slightly malformed input:
    * If an interval has only one element, it is treated as a point interval
      where start == end.
    * If an interval has more than two elements, only the first two are used.
    * If the first element is greater than the second, they are swapped so that
      start <= end.
    The result is a list of merged [start, end] intervals sorted by start.
    """
    if not intervals:
        return []
    normalized = []
    for iv in intervals:
        # Ensure iv is indexable
        try:
            length = len(iv)
        except Exception:
            continue
        if length == 0:
            continue
        if length == 1:
            a = iv[0]
            b = a
        else:
            a = iv[0]
            b = iv[1]
        # Make sure we can compare; if not, skip this interval
        try:
            if a <= b:
                start, end = a, b
            else:
                start, end = b, a
        except Exception:
            continue
        normalized.append([start, end])
    if not normalized:
        return []
    # Sort intervals by start then end
    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end = normalized[0]
    for start, end in normalized[1:]:
        if start <= cur_end:  # overlap or touch
            cur_end = max(cur_end, end)
